        with open(path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    else:
        raise ValueError(f"Unsupported config format: {suffix}")
    if not isinstance(config, dict):
        raise ValueError("Config must be a dictionary")
    return config

def find_default_config(repo_root: str = '.') -> dict | None:
    base = Path(repo_root)
    for name in ('harness_config.json', 'harness_config.yaml', 'harness_config.yml'):
        path = base / name
        if path.exists():
            return load_config(str(path))
    return None

from mini_harness.harness import DagRunner
from mini_harness.repo import get_repo_root
from pathlib import Path

def run_dag(input_files):
    repo_root = get_repo_root()
    resolved = []
    for f in input_files:
        p = Path(f)
        if not p.is_absolute():
            p = Path(repo_root) / p
        resolved.append(str(p))
    runner = DagRunner()
    return runner.run(resolved)
